home:
:root {
  --azul-primario: #102A43;
  --azul-escuro: #102a43;
  --laranja-titulo: #dd7b2d;
  --azul-ecossistema: #102a43;
  --creme: #f8f5f0;
  --branco: #ffffff;
  --texto-escuro: #181818;
  --texto-corpo: #424842;
  --borda-card: #e2e3df;
  --laranja: #dd7b2d;
  --bege: #F8B983;

  --fonte: "DM Sans", sans-serif;
  --radius-botao: 4px;
  --radius-card: 20px;
  --sombra-card: 0 4px 12px rgba(0, 0, 0, 0.08);
}

/* ---------- Reset básico ---------- */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--fonte);
  background-color: var(--creme);
  color: var(--texto-escuro);
  line-height: 1.5;
}

img {
  max-width: 100%;
  display: block;
}

p,
h1,
h2,
h3 {
  cursor: default;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

h1,
h2,
h3 {
  font-weight: 700;
  line-height: 1.2;
}

section {
  padding: 80px 8%;
}

.destaque-salmao {
  color: var(--bege);
}

.sublinha-salmao {
  text-decoration: underline;
  text-decoration-color: var(--bege);
  text-decoration-thickness: 3px;
  text-underline-offset: 4px;
}

.btn {
  display: inline-block;
  padding: 12px 15px;
  border-radius: var(--radius-botao);
  font-weight: 700;
  font-size: 16.91px;
  -webkit-tap-highlight-color: transparent;
  transition:
          transform 0.2s ease,
          background-color 0.2s ease,
          border-color 0.2s ease;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-primario {
  background-color: var(--azul-primario);
  color: var(--creme);
  box-shadow: 0 4px 10px rgba(32, 65, 43, 0.25);
}

.btn-primario:hover {
  background-color: #1a3a5c;
}

.btn-secundario {
  background-color: transparent;
  color: var(--texto-escuro);
  border: 1.5px solid var(--texto-escuro);
}

.btn-secundario:hover {
  background-color: rgba(24, 24, 24, 0.05);
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 8%;
  background-color: var(--branco);
}

.logo img {
  height: 48px;
  width: auto;
}

header nav ul {
  display: flex;
  gap: 40px;
}

header nav a {
  font-size: 23px;
  font-weight: 300;
  position: relative;
  padding-bottom: 6px;
}

header nav a:hover {
  color: var(--azul-primario);
}

header nav a.ativo {
  text-decoration: underline;
  text-underline-offset: 4px;
  font-weight: 700;
}

.btn-contato {
  background-color: var(--azul-primario);
  color: var(--creme);
  padding: 14px;
  border-radius: var(--radius-botao);
  font-weight: 500;
  font-size: 21px;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.2s ease;
}

.btn-contato:hover {
  background-color: #1a3a5c;
}

main {
  position: relative;
  overflow: hidden;
}

#background-line {
  position: absolute;
  right: 45px;
  top: -45px;
  z-index: -2;
  max-height: 19%;
  rotate: 4deg;
}

.hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding-top: 160px;
  padding-bottom: 60px;
}

.hero-texto {
  max-width: 600px;
}

.hero-texto h1 {
  font-size: 60px;
  margin-bottom: 24px;
}

.hero-texto .destaque {
  color: var(--laranja-titulo);
}

.hero-texto p {
  font-size: 28.74px;
  color: var(--texto-corpo);
  margin-bottom: 32px;
}

.hero-botoes {
  display: flex;
  gap: 36.27px;
}

.hero-imagem {
  display: flex;
  justify-content: center;
  position: relative;
}

.hero-imagem #mock-left {
  position: absolute;
  max-width: 392px;
  rotate: 7deg;
  left: -530px;
  top: -219px;
}

.hero-imagem #mock-right {
  position: absolute;
  bottom: -164px;
  right: -83px;
  max-width: 414px;
  rotate: -2.78deg;
}

.sistema h2,
.funcionalidades h2 {
  width: max-content;
  max-width: 90%;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  padding-bottom: 14px;
}

.sistema h2::after,
.funcionalidades h2::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 1.5px;
  background-color: rgba(221, 123, 45, 0.5);
}

.sistema h2 {
  text-align: center;
  font-size: 40px;
  color: var(--azul-ecossistema);
  font-weight: 600;
  margin-bottom: 48px;
}

.cards-sistema {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.cards-sistema .card {
  background-color: var(--branco);
  border-radius: var(--radius-card);
  overflow: hidden;
  box-shadow: var(--sombra-card);
  display: flex;
  flex-direction: column;
  transition:
          transform 0.25s ease,
          box-shadow 0.25s ease;
}

.cards-sistema .card:hover {
  transform: translateY(-6px) scale(1.03);
  box-shadow: 0 14px 28px rgba(0, 0, 0, 0.14);
}

.cards-sistema .card img {
  width: 100%;
  height: 160px;
  object-fit: cover;
}

.cards-sistema .card h3 {
  font-size: 20px;
  padding: 20px 20px 8px;
}

.cards-sistema .card p {
  font-size: 15px;
  color: var(--texto-corpo);
  padding: 0 20px 24px;
}

.funcionalidades h2 {
  text-align: center;
  font-size: 36px;
  color: var(--azul-primario);
  margin-bottom: 48px;
}

.grid-funcionalidades {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: minmax(200px, auto);
  gap: 24px;
}

.func-card {
  background-color: var(--branco);
  border: 1px solid var(--borda-card);
  border-radius: var(--radius-card);
  padding: 32px;
  box-shadow: var(--sombra-card);
  transition:
          transform 0.25s ease,
          box-shadow 0.25s ease;
}

.func-card:hover {
  transform: translateY(-6px) scale(1.02);
  box-shadow: 0 14px 28px rgba(0, 0, 0, 0.14);
}

.func-icone {
  width: 28px;
  height: 28px;
  margin-bottom: 16px;
}

/* O SVG recebido conserva suas dimensões intrínsecas, sem deformar o ícone. */
.func-icone[src$=".svg"] {
  width: auto;
  height: auto;
}

.func-card h3 {
  font-size: 22px;
  font-weight: 500;
  margin-bottom: 12px;
}

.func-card p {
  font-size: 16px;
  color: var(--texto-corpo);
}

.func-destaque {
  background-color: var(--azul-primario);
  border: none;
}

.func-destaque h3,
.func-destaque p {
  color: var(--creme);
}

.func-largo {
  grid-column: span 2;
  display: flex;
  align-items: center;
  gap: 32px;
}

.func-largo .func-texto {
  flex: 1;
  min-width: 0;
}

.func-largo .func-ilustracao {
  flex: 1;
  width: auto;
  max-width: 380px;
  margin-top: 0;
}

.func-alto {
  grid-row: span 2;
  display: flex;
  flex-direction: column;
}

.func-ilustracao {
  margin-top: 20px;
  width: 100%;
}

.func-alto .func-ilustracao {
  margin-top: auto;
}

.estatistica {
  display: flex;
  align-items: stretch;
  padding: 30px 0;
  background-color: transparent;
  color: var(--creme);
}

.estatistica-foto {
  width: 39.3%;
  height: auto;
  flex-shrink: 0;
  position: relative;
  z-index: 2;
}

.estatistica-conteudo {
  flex: 1;
  margin: 47px 0 64px -1.9%;
  padding: 0 8% 0 6.4%;
  background-color: var(--azul-primario);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.estatistica-conteudo .numero-grande {
  font-size: 90px;
  font-weight: 700;
  color: var(--branco);
  margin-bottom: 16px;
}

.estatistica-conteudo h2 {
  font-size: 28px;
  margin-bottom: 20px;
}

.estatistica-conteudo p {
  font-size: 26px;
  letter-spacing: 0.66px;
  max-width: 600px;
}

.secao-linhas-decorativas {
  position: relative;
  overflow: hidden;
}

#ecossistema-linha {
  position: absolute;
  top: 40%;
  left: 0;
  width: 100%;
  height: auto;
  z-index: -1;
  pointer-events: none;
  opacity: 0.5;
}

#cta-final-linha {
  position: absolute;
  top: 7%;
  right: 0;
  left: auto;
  width: 95%;        
  height: auto;
  z-index: -1;
  pointer-events: none;
  opacity: 0.6;
}

.ecossistema {
  display: flex;
  align-items: center;
  gap: 40px;
  padding-left: 0;
  padding-right: 8%;
  position: relative;
}

.ecossistema-imagem {
  flex: 0 0 35%;
  position: relative;
  z-index: 1;
}

.ecossistema-imagem img {
  width: 100%;
}

.ecossistema-texto {
  flex: 1;
  position: relative;
  z-index: 1;
  text-align: right;
  padding-right: 0;
}

.ecossistema-texto h2 {
  font-size: 50px;
  font-weight: 800;
  letter-spacing: 0.69px;
  color: var(--azul-ecossistema);
  margin-bottom: 20px;
  text-align: right;
}

.ecossistema-texto p {
  font-size: 27.74px;
  font-weight: 500;
  letter-spacing: 0.69px;
  color: var(--texto-escuro);
  text-align: right;
  margin-left: auto;
  max-width: 590px;
}

.cta-final {
  padding: 100px 8%;
  position: relative;
}

.cta-final-conteudo {
  display: flex;
  align-items: center;
  gap: 40px;
  position: relative;
  z-index: 1;
}

.cta-final-texto {
  flex: 1;
  max-width: 500px;
}

.cta-final h2 {
  font-size: 36px;
  margin-bottom: 16px;
}

.cta-final p {
  font-size: 18px;
  color: var(--texto-corpo);
  margin-bottom: 32px;
}

.cta-botoes {
  display: flex;
  gap: 16px;
}

.cta-final-imagem {
  flex: 1;
  position: relative;
}

.cta-final-imagem .mascote-cta {
  position: absolute;
  right: 2%;
  bottom: -6%;
  width: 30%;
  max-width: 220px;
  z-index: 2;
}

footer {
  background-color: var(--branco);
  padding: 60px 8% 30px;
}

.footer-topo {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 32px;
  margin-bottom: 40px;
}

.footer-logo img {
  height: 28px;
  width: auto;
}

.footer-logo p {
  margin-top: 12px;
  font-size: 15px;
  color: var(--texto-corpo);
  max-width: 200px;
}

.footer-coluna h5 {
  font-size: 16.08px;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: var(--azul-escuro);
  margin-bottom: 16px;
}

.footer-coluna ul li {
  font-size: 18.38px;
  color: var(--texto-corpo);
  margin-bottom: 12px;
}

footer hr {
  border: none;
  border-top: 1.15px solid var(--borda-card);
  margin-bottom: 20px;
}

.footer-base p {
  font-size: 13.78px;
  letter-spacing: 0.69px;
  font-weight: 500;
  color: var(--texto-corpo);
  text-align: left;
}

@media (max-width: 900px) {
  header {
    flex-direction: column;
    gap: 16px;
  }

  header nav ul {
    gap: 20px;
  }

  .hero {
    flex-direction: column;
    text-align: center;
  }

  .hero-texto h1 {
    font-size: 34px;
  }

  .cards-sistema {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-funcionalidades {
    grid-template-columns: 1fr;
  }

  .func-largo,
  .func-alto {
    grid-column: span 1;
    grid-row: span 1;
  }

  .func-largo {
    flex-direction: column;
    align-items: stretch;
  }

  .func-largo .func-ilustracao {
    max-width: 100%;
  }

  .estatistica {
    flex-direction: column;
    padding: 0;
  }

  .estatistica-foto {
    width: 100%;
    height: 220px;
    object-fit: cover;
  }

  .estatistica-conteudo {
    margin: 0;
    padding: 40px 6%;
  }

  .ecossistema {
    flex-direction: column;
    text-align: center;
    padding-left: 6%;
  }

  .ecossistema-imagem {
    flex-basis: auto;
    width: 100%;
  }

  #ecossistema-linha,
  #cta-final-linha {
    display: none;
  }

  .cta-final-conteudo {
    flex-direction: column;
    text-align: center;
  }

  .footer-topo {
    flex-direction: column;
  }
}

@media (max-width: 500px) {
  section {
    padding: 60px 6%;
  }

  .cards-sistema {
    grid-template-columns: 1fr;
  }

  .estatistica-conteudo .numero-grande {
    font-size: 60px;
  }
}

/* ===== Ajustes paralelos a partir do frame Landing / Home 91:9137 ===== */
body > main { overflow:hidden; }
main > .hero { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); min-height:740px; padding:90px 82px 30px; gap:50px; align-items:center; }
.hero-texto { max-width:610px; }
.hero-texto h1 { max-width:560px; margin:0 0 26px; font-size:60px; line-height:1.15; letter-spacing:-1px; }
.hero-texto p { max-width:610px; font-size:28px; line-height:1.6; margin-bottom:30px; }
.hero-botoes { gap:30px; }
.hero-imagem { position:relative; height:610px; min-width:0; width:100%; }
.hero-imagem #mock-left { rotate:0deg; width:min(78%,392px); height:auto; max-width:392px; left:0; right:auto; top:145px; bottom:auto; z-index:1; }
.hero-imagem #mock-right { rotate:0deg; width:min(82%,415px); height:auto; max-width:415px; right:-15px; top:5px; bottom:auto; z-index:2; }
.hero-imagem::after { content:""; position:absolute; width:105%; height:55px; background:#102a430a; border-radius:50%; bottom:-5px; left:-30px; }
#background-line { top:105px; right:-80px; width:800px; max-height:none; rotate:0deg; z-index:-1; }
main .btn-secundario { border-color:#f8b983; background:transparent; color:#181818; }
main #sistema { min-height:570px; padding:15px 48px 95px; }
#sistema h2 { margin:0 auto 65px; width:fit-content; max-width:100%; font-size:38px; line-height:1.3; font-weight:600; padding-bottom:10px; border-bottom:2px solid #f8b983; }
.cards-sistema { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:52px; }
.cards-sistema .card { min-width:0; min-height:350px; margin:0; border-radius:9px; box-shadow:0 5px 8px #0004; background:#f5f7fa; overflow:hidden; }
.cards-sistema .card img { display:block; width:100%; height:160px; object-fit:cover; }
.cards-sistema .card h3 { margin:18px 16px 10px; padding:0; font-size:20px; line-height:1.35; }
.cards-sistema .card p { margin:0 16px 20px; padding:0; font-size:16px; line-height:1.5; }
main .estatistica { display:grid; grid-template-columns:38% minmax(0,1fr); align-items:center; gap:0; min-height:685px; padding:0; margin:0 0 110px; background:#102a43; color:#f5f7fa; }
.estatistica-imagem { height:685px; }
.estatistica-imagem img { display:block; width:100%; height:685px; object-fit:cover; margin:0; box-shadow:0 5px 10px #0003; }
.estatistica-conteudo { padding:45px 70px; }
.estatistica-conteudo .numero-grande { font-size:145px; line-height:1.05; margin:0 0 8px; color:#f5f7fa; }
.estatistica-conteudo h3 { font-size:32px; line-height:1.45; margin:0 0 35px; color:#f5f7fa; }
.estatistica-conteudo p { font-size:23px; line-height:1.7; color:#e7edf1; }
main #funcionalidades { padding:0 50px 75px; }
#funcionalidades > h2 { width:fit-content; margin:0 auto 55px; padding-bottom:8px; font-size:34px; border-bottom:2px solid #f8b983; }
.grid-funcionalidades { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); grid-auto-rows:minmax(265px,auto); gap:24px; }
.func-card { padding:34px; border:1px solid #f1f5f8; border-radius:26px; box-shadow:0 4px 4px #0003; background:#f5f7fa; }
.func-card h3 { font-size:24px; line-height:1.3; font-weight:400; margin:0 0 20px; }
.func-card p { font-size:17px; line-height:1.55; margin:0; color:#334553; }
.func-icone { object-fit:contain; }
.func-largo { grid-column:span 2; display:flex; align-items:center; gap:35px; }
.func-largo .func-ilustracao { width:48%; max-width:390px; height:auto; object-fit:contain; }
.func-destaque { background:#102a43; border-color:#102a43; }
.func-destaque h3,.func-destaque p { color:#f5f7fa; }
.func-alto { grid-column:3; grid-row:2 / span 2; }
.func-alto .func-ilustracao { display:block; width:100%; max-width:357px; height:auto; margin:30px auto 0; }
main .ecossistema { display:grid; grid-template-columns:50% 50%; min-height:780px; padding:45px 55px 30px 0; gap:0; }
.ecossistema-imagem { min-width:0; align-self:center; }
.ecossistema-imagem img { display:block; width:100%; max-width:650px; height:auto; }
.ecossistema-texto { padding:0 25px 0 45px; text-align:center; }
.ecossistema-texto h2 { font-size:45px; line-height:1.35; margin:0 0 32px; }
.ecossistema-texto p { font-size:27px; line-height:1.6; }
#ecossistema-linha { top:12%; left:0; width:100%; z-index:-1; opacity:.75; }
#cta-final-linha { top:30%; right:0; width:100%; z-index:-1; opacity:.75; }
main .cta-final { min-height:700px; padding:60px 48px 100px; }
.cta-final-conteudo { display:grid; grid-template-columns:45% minmax(0,1fr); gap:30px; align-items:center; }
.cta-final-texto h2 { font-size:45px; line-height:1.35; margin:0 0 30px; }
.cta-final-texto p { font-size:26px; line-height:1.6; margin-bottom:35px; }
.cta-final-imagem { min-width:0; }
.cta-final-imagem > img { display:block; width:100%; max-width:680px; height:auto; }
@media(max-width:1100px) { main > .hero { padding:70px 45px 30px; min-height:650px; gap:25px; } .hero-texto h1 { font-size:46px; } .hero-texto p { font-size:22px; } .hero-imagem { height:500px; } .hero-imagem #mock-left { top:125px; } main #sistema { padding-left:30px; padding-right:30px; } #sistema h2 { font-size:29px; } .cards-sistema { gap:24px; } .estatistica-conteudo { padding:35px; } .estatistica-conteudo .numero-grande { font-size:110px; } .estatistica-conteudo h3 { font-size:26px; } .estatistica-conteudo p { font-size:19px; } main #funcionalidades { padding-left:30px; padding-right:30px; } .func-card { padding:25px; } .func-card h3 { font-size:20px; } .func-card p { font-size:15px; } .ecossistema-texto { padding:0 20px; } .ecossistema-texto h2,.cta-final-texto h2 { font-size:34px; } .ecossistema-texto p,.cta-final-texto p { font-size:21px; } main .ecossistema { min-height:620px; padding-right:30px; } main .cta-final { min-height:580px; padding:50px 30px; } }
