.card-plano#principal .tag { left:50%; }
.card-plano#principal .atributos li { font-size:15px; }
@media(max-width:1100px) { section#escolha-plano .container { gap:25px; } }
@media(max-width:767px) { section#escolha-plano .container { grid-template-columns:1fr; gap:50px; } }
/* Rodada 2: a decoração pertence somente à metade direita do hero. */
#hero { overflow:hidden; isolation:isolate; }
section#hero #background-lines { inset:0 0 0 auto; width:50%; height:100%; overflow:hidden; opacity:1; }
#hero #background-lines img { width:100%; height:100%; object-fit:cover; object-position:left center; }
#hero #left { max-width:50%; }
/* DOM/JS V7 restaurados, mantendo as dimensões visuais do protótipo. */
section#escolha-plano #toggle-plano { display:flex; align-items:center; gap:0; width:310px; height:60px; padding:6px; margin:0 auto 95px; box-sizing:border-box; }
section#escolha-plano #toggle-plano .opcao { flex:1; width:149px; height:48px; padding:9px 22px; border:0; background:transparent; font-family:inherit; }
section#escolha-plano #toggle-plano #retangulo { pointer-events:none; }
section#escolha-plano #toggle-plano .opcao:focus-visible { outline:3px solid #dd7b2d; outline-offset:2px; }
@media(max-width:1100px) { #hero #left { max-width:50%; } #hero h1 { font-size:40px; } #hero p { font-size:22px; } }
@media(max-width:767px) { #hero #left { max-width:100%; } #hero #background-lines { opacity:.18; } #hero h1 { font-size:40px; } #hero p { font-size:21px; } section#escolha-plano #toggle-plano { max-width:100%; margin-bottom:65px; } }
/* Rodada 4: padrão isolado no hero; posição proporcional ao frame de 1440 px. */
section#hero #background-lines { width:52.916667%; }
#hero #background-lines img { height:auto; position:absolute; top:-93px; left:0; }
@media(max-width:767px) { #hero #background-lines img { height:100%; width:auto; max-width:none; top:0; left:auto; right:0; } }
